    final AtomicBoolean onNext = new AtomicBoolean(false);
    final AtomicBoolean onCompleted = new AtomicBoolean(false);

    Observable<String> o = Observable.just("Hallo")
        .doOnNext(new Action1<String>() {
          @Override
          public void call(String s) {
            onNext.set(true);
          }
        })
        .doOnCompleted(new Action0() {
          @Override
          public void call() {
            onCompleted.set(true);
          }
        });

    ConnectableObservable<String> connectable = o.replay();
    connectable.connect();

    assertTrue(onNext.get());
    assertTrue(onCompleted.get());
  }
